import re
from difflib import SequenceMatcher
from openai import OpenAI

client = OpenAI()
MODEL = "gpt-4.1-mini"  # any chat model under suspicion

def ngrams(text: str, n: int = 13) -> set[tuple[str, ...]]:
    toks = re.findall(r"\w+", text.lower())
    return {tuple(toks[i:i + n]) for i in range(len(toks) - n + 1)}

def overlap_rate(eval_items: list[str], train_docs: list[str], n: int = 13) -> float:
    # Probe 1, data you control: did eval items leak into your fine-tuning set?
    seen = set().union(*(ngrams(d, n) for d in train_docs))
    return sum(bool(ngrams(x, n) & seen) for x in eval_items) / len(eval_items)

def completion_probe(item: str) -> float:
    # Probe 2, closed model: can it finish a test item it should never have seen?
    cut = len(item) // 2
    out = client.chat.completions.create(
        model=MODEL, temperature=0,
        messages=[{"role": "user", "content": f"Continue this text exactly:\n{item[:cut]}"}],
    ).choices[0].message.content or ""
    return SequenceMatcher(None, out[: len(item) - cut], item[cut:]).ratio()

